#include <CGAL/Polygon_2.h>
#include <CGAL/convex_hull_2.h>
#include <CGAL/Boolean_set_operations_2.h>
#include <CGAL/Exact_predicates_exact_constructions_kernel.h>
#include <cmath>
#include <iostream>
#include <vector>
#include <string>
#include <limits>
#include <cstdlib>
#include <chrono>
#include <iomanip>
#include <random>
#include <set>
#include <algorithm>
#include <cassert>

using Kernel = CGAL::Exact_predicates_exact_constructions_kernel;
using Point = Kernel::Point_2;
using Polygon = CGAL::Polygon_2<Kernel>;
using Polygon_with_holes = CGAL::Polygon_with_holes_2<Kernel>;

std::mt19937 rng(42);  // Fixed seed for reproducibility

// ============== point_in_convex ==============
bool point_in_convex(const Point &p, const std::vector<Point> &poly, bool ccw = true) {
    for (size_t i = 0, n = poly.size(); i < n; ++i) {
        const auto &a = poly[i];
        const auto &b = poly[(i + 1) % n];
        if (CGAL::orientation(a, b, p) == (ccw ? CGAL::RIGHT_TURN : CGAL::LEFT_TURN))
            return false;
    }
    return true;
}

// ============== O'Rourke's convex polygon intersection ==============
std::vector<Point> convex_polygon_intersection(const std::vector<Point>& P_input,
                                                const std::vector<Point>& Q_input) {
    if (P_input.empty() || Q_input.empty()) return {};

    std::vector<Point> P = P_input;
    std::vector<Point> Q = Q_input;

    if (CGAL::area(Kernel::Point_2(0,0), P[0], P[1]) < 0) {
        std::reverse(P.begin(), P.end());
    }
    if (CGAL::area(Kernel::Point_2(0,0), Q[0], Q[1]) < 0) {
        std::reverse(Q.begin(), Q.end());
    }

    int n = static_cast<int>(P.size());
    int m = static_cast<int>(Q.size());

    if (n < 3 || m < 3) {
        return {};
    }

    double min_x =  std::numeric_limits<double>::max();
    double max_x = -std::numeric_limits<double>::max();
    double min_y =  std::numeric_limits<double>::max();
    double max_y = -std::numeric_limits<double>::max();
    for (const auto& p : P) {
        min_x = std::min(min_x, CGAL::to_double(p.x()));
        max_x = std::max(max_x, CGAL::to_double(p.x()));
        min_y = std::min(min_y, CGAL::to_double(p.y()));
        max_y = std::max(max_y, CGAL::to_double(p.y()));
    }
    for (const auto& q : Q) {
        min_x = std::min(min_x, CGAL::to_double(q.x()));
        max_x = std::max(max_x, CGAL::to_double(q.x()));
        min_y = std::min(min_y, CGAL::to_double(q.y()));
        max_y = std::max(max_y, CGAL::to_double(q.y()));
    }
    double scale = std::max(max_x - min_x, max_y - min_y);
    const double EPS = std::max(scale * 1e-10, 1e-12);
    const double CLOSE = std::max(scale * 1e-6, 1e-8);

    bool all_P_in_Q = true;
    bool all_Q_in_P = true;
    for (const auto& p : P) {
        if (!point_in_convex(p, Q, true)) {
            all_P_in_Q = false;
            break;
        }
    }
    if (all_P_in_Q) return P;

    for (const auto& q : Q) {
        if (!point_in_convex(q, P, true)) {
            all_Q_in_P = false;
            break;
        }
    }
    if (all_Q_in_P) return Q;

    int i = 0, j = 0;
    std::vector<Point> result;
    bool first_intersection_found = false;
    Point first_intersection;
    int max_iterations = 2 * (n + m) + 10;
    int iterations = 0;

    auto cross = [](const Point& o, const Point& a, const Point& b) {
        return (CGAL::to_double(a.x()) - CGAL::to_double(o.x())) * (CGAL::to_double(b.y()) - CGAL::to_double(o.y())) -
               (CGAL::to_double(a.y()) - CGAL::to_double(o.y())) * (CGAL::to_double(b.x()) - CGAL::to_double(o.x()));
    };

    auto advance_i = [&]() { i = (i + 1) % n; };
    auto advance_j = [&]() { j = (j + 1) % m; };

    auto segments_intersect = [&](const Point& a1, const Point& a2,
                                   const Point& b1, const Point& b2) -> std::optional<Point> {
        double x1 = CGAL::to_double(a1.x()), y1 = CGAL::to_double(a1.y());
        double x2 = CGAL::to_double(a2.x()), y2 = CGAL::to_double(a2.y());
        double x3 = CGAL::to_double(b1.x()), y3 = CGAL::to_double(b1.y());
        double x4 = CGAL::to_double(b2.x()), y4 = CGAL::to_double(b2.y());

        double denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
        if (std::abs(denom) < EPS) return std::nullopt;

        double t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / denom;
        double u = -((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / denom;

        if (t >= -EPS && t <= 1.0 + EPS && u >= -EPS && u <= 1.0 + EPS) {
            return Point(x1 + t * (x2 - x1), y1 + t * (y2 - y1));
        }
        return std::nullopt;
    };

    while (iterations < max_iterations) {
        iterations++;

        const Point& pi = P[i];
        const Point& pj = Q[j];
        const Point& p_next_i = P[(i + 1) % n];
        const Point& p_next_j = Q[(j + 1) % m];

        if (point_in_convex(pi, Q, true)) {
            result.push_back(pi);
        }
        if (point_in_convex(pj, P, true)) {
            result.push_back(pj);
        }

        auto inter = segments_intersect(pi, p_next_i, pj, p_next_j);

        if (inter) {
            if (!first_intersection_found) {
                first_intersection = *inter;
                first_intersection_found = true;
            } else {
                double dist = std::sqrt(CGAL::to_double(CGAL::squared_distance(*inter, first_intersection)));
                if (dist < CLOSE && result.size() > 2) {
                    if (result.empty() ||
                        std::sqrt(CGAL::to_double(CGAL::squared_distance(*inter, result.back()))) > CLOSE) {
                        result.push_back(*inter);
                    }
                    break;
                }
            }
            if (result.empty() ||
                std::sqrt(CGAL::to_double(CGAL::squared_distance(*inter, result.back()))) > CLOSE) {
                result.push_back(*inter);
            }
        }

        double cross_val = cross(pi, p_next_i, pj);
        double cross_val2 = cross(pj, p_next_j, pi);

        if (std::abs(cross_val) < EPS && std::abs(cross_val2) < EPS) {
            advance_i();
            advance_j();
        } else if (cross_val >= 0 && cross_val2 >= 0) {
            if (cross(pi, p_next_i, pj) <= cross(pj, p_next_j, pi)) {
                advance_i();
            } else {
                advance_j();
            }
        } else if (cross_val >= 0) {
            advance_i();
        } else {
            advance_j();
        }

        if (i == 0 && j == 0 && iterations > n + m) {
            break;
        }
    }

    if (result.size() > 1) {
        std::vector<Point> deduped;
        deduped.push_back(result[0]);
        for (size_t k = 1; k < result.size(); k++) {
            double dist = std::sqrt(CGAL::to_double(CGAL::squared_distance(result[k], deduped.back())));
            if (dist > CLOSE) {
                deduped.push_back(result[k]);
            }
        }
        result = deduped;
    }

    if (result.size() > 2) {
        std::vector<Point> clean;
        clean.push_back(result[0]);
        for (size_t k = 1; k < result.size(); k++) {
            const Point& prev = clean.back();
            const Point& curr = result[k];
            const Point& next = result[(k + 1) % result.size()];
            double area = CGAL::to_double(CGAL::area(prev, curr, next));
            if (std::abs(area) > EPS) {
                clean.push_back(curr);
            }
        }
        result = clean;
    }

    return result;
}

// ============== Helper functions for CGAL reference ==============
std::vector<Point> polygon_to_vector(const Polygon& poly) {
    std::vector<Point> result;
    for (auto it = poly.vertices_begin(); it != poly.vertices_end(); ++it) {
        result.push_back(*it);
    }
    return result;
}

Polygon vector_to_polygon(const std::vector<Point>& pts) {
    return Polygon(pts.begin(), pts.end());
}

bool polygons_equal(const std::vector<Point>& A, const Polygon& B) {
    if (A.empty()) return B.is_empty();
    if (B.is_empty()) return A.empty();

    std::vector<Point> Bvec = polygon_to_vector(B);

    // Check both orientations (A could be CW or CCW)
    auto check_match = [&](const std::vector<Point>& a, const std::vector<Point>& b) -> bool {
        if (a.size() != b.size()) return false;
        size_t n = a.size();
        // Find starting point in B
        size_t start = 0;
        for (size_t i = 0; i < n; i++) {
            double dx = CGAL::to_double(a[0].x()) - CGAL::to_double(b[i].x());
            double dy = CGAL::to_double(a[0].y()) - CGAL::to_double(b[i].y());
            if (std::abs(dx) < 1e-9 && std::abs(dy) < 1e-9) {
                start = i;
                break;
            }
        }
        // Check if sequence matches
        for (size_t k = 0; k < n; k++) {
            size_t idx = (start + k) % n;
            double dx = CGAL::to_double(a[k].x()) - CGAL::to_double(b[idx].x());
            double dy = CGAL::to_double(a[k].y()) - CGAL::to_double(b[idx].y());
            if (std::abs(dx) > 1e-9 || std::abs(dy) > 1e-9) {
                return false;
            }
        }
        return true;
    };

    return check_match(A, Bvec) || check_match(A, std::vector<Point>(Bvec.rbegin(), Bvec.rend()));
}

double polygon_area(const std::vector<Point>& poly) {
    if (poly.size() < 3) return 0;
    double area = 0;
    for (size_t i = 0; i < poly.size(); i++) {
        size_t j = (i + 1) % poly.size();
        area += CGAL::to_double(poly[i].x()) * CGAL::to_double(poly[j].y());
        area -= CGAL::to_double(poly[j].x()) * CGAL::to_double(poly[i].y());
    }
    return std::abs(area) / 2.0;
}

// ============== Test case generators ==============

std::vector<Point> make_regular_polygon(double cx, double cy, double r, int n) {
    std::vector<Point> poly;
    for (int i = 0; i < n; i++) {
        double angle = 2 * M_PI * i / n - M_PI / 2;
        poly.emplace_back(cx + r * std::cos(angle), cy + r * std::sin(angle));
    }
    return poly;
}

std::vector<Point> make_rectangle(double x1, double y1, double x2, double y2) {
    return {
        Point(x1, y1), Point(x2, y1), Point(x2, y2), Point(x1, y2)
    };
}

std::vector<Point> make_triangle(double x1, double y1, double x2, double y2,
                                  double x3, double y3) {
    return {Point(x1, y1), Point(x2, y2), Point(x3, y3)};
}

std::vector<Point> make_random_convex(int n, double range) {
    std::vector<Point> pts;
    int attempts = 0;
    while ((int)pts.size() < n && attempts < 1000) {
        Point p(std::uniform_real_distribution<>(-range, range)(rng),
                std::uniform_real_distribution<>(-range, range)(rng));
        bool valid = true;
        for (size_t i = 0; i < pts.size() && valid; i++) {
            for (size_t j = i + 1; j < pts.size() && valid; j++) {
                double dist = std::sqrt(CGAL::to_double(CGAL::squared_distance(pts[i], pts[j])));
                if (dist < 0.1) valid = false;
            }
        }
        if (valid) pts.push_back(p);
        attempts++;
    }

    if (pts.size() >= 3) {
        Polygon hull(pts.begin(), pts.end());
        hull = hull.convex_hull();
        pts.clear();
        for (auto it = hull.vertices_begin(); it != hull.vertices_end(); ++it) {
            pts.push_back(*it);
        }
    }

    while ((int)pts.size() < 3) {
        pts.emplace_back(std::uniform_real_distribution<>(-range, range)(rng),
                        std::uniform_real_distribution<>(-range, range)(rng));
    }

    return pts;
}

std::vector<Point> perturb_polygon(const std::vector<Point>& poly, double amount) {
    std::vector<Point> result;
    for (const auto& p : poly) {
        result.emplace_back(
            CGAL::to_double(p.x()) + std::uniform_real_distribution<>(-amount, amount)(rng),
            CGAL::to_double(p.y()) + std::uniform_real_distribution<>(-amount, amount)(rng)
        );
    }
    return result;
}

std::vector<Point> scale_polygon(const std::vector<Point>& poly, double sx, double sy, double cx = 0, double cy = 0) {
    std::vector<Point> result;
    for (const auto& p : poly) {
        result.emplace_back(
            cx + sx * (CGAL::to_double(p.x()) - cx),
            cy + sy * (CGAL::to_double(p.y()) - cy)
        );
    }
    return result;
}

std::vector<Point> rotate_polygon(const std::vector<Point>& poly, double angle, double cx = 0, double cy = 0) {
    double cos_a = std::cos(angle);
    double sin_a = std::sin(angle);
    std::vector<Point> result;
    for (const auto& p : poly) {
        double x = CGAL::to_double(p.x()) - cx;
        double y = CGAL::to_double(p.y()) - cy;
        result.emplace_back(cx + x * cos_a - y * sin_a, cy + x * sin_a + y * cos_a);
    }
    return result;
}

// ============== Test case structures ==============
struct TestResult {
    std::string name;
    bool our_empty;
    bool cgal_empty;
    bool match;
    double our_area;
    double cgal_area;
    int our_vertices;
    int cgal_vertices;
    std::string details;
};

// ============== Main test runner ==============
int main() {
    std::cout << "==========================================\n";
    std::cout << "Convex Polygon Intersection Test Suite\n";
    std::cout << "==========================================\n\n";

    std::vector<TestResult> results;
    int pass_count = 0;
    int fail_count = 0;
    int total_tests = 0;

    // --- Basic geometric shapes ---

    // 1. Two identical squares
    {
        total_tests++;
        auto P = make_rectangle(0, 0, 10, 10);
        auto Q = make_rectangle(0, 0, 10, 10);
        auto our = convex_polygon_intersection(P, Q);
        Polygon poly_P(P.begin(), P.end()), poly_Q(Q.begin(), Q.end());
        auto cgal_result = CGAL::intersection(poly_P, poly_Q);

        bool our_empty = our.empty() || our.size() < 3;
        bool cgal_empty = !cgal_result || std::holds_alternative<Polygon_with_holes>(*cgal_result) == false;
        Polygon cgal_poly;
        if (cgal_result) {
            if (auto* pp = std::get_if<Polygon>(&*cgal_result)) cgal_poly = *pp;
            else if (auto* pwh = std::get_if<Polygon_with_holes>(&*cgal_result)) cgal_poly = pwh->outer_boundary();
        }

        bool match = our_empty ? cgal_empty : polygons_equal(our, cgal_poly);
        if (match) pass_count++; else fail_count++;
        results.push_back({"Identical squares", our_empty, cgal_empty, match,
                          polygon_area(our), polygon_area(cgal_poly),
                          (int)our.size(), (int)std::distance(cgal_poly.vertices_begin(), cgal_poly.vertices_end()),
                          ""});
    }

    // 2. Two overlapping squares
    {
        total_tests++;
        auto P = make_rectangle(0, 0, 10, 10);
        auto Q = make_rectangle(5, 5, 15, 15);
        auto our = convex_polygon_intersection(P, Q);
        Polygon poly_P(P.begin(), P.end()), poly_Q(Q.begin(), Q.end());
        auto cgal_result = CGAL::intersection(poly_P, poly_Q);

        bool our_empty = our.empty() || our.size() < 3;
        bool cgal_empty = !cgal_result;
        Polygon cgal_poly;
        if (cgal_result) {
            if (auto* pp = std::get_if<Polygon>(&*cgal_result)) cgal_poly = *pp;
            else if (auto* pwh = std::get_if<Polygon_with_holes>(&*cgal_result)) cgal_poly = pwh->outer_boundary();
        }

        bool match = our_empty ? cgal_empty : polygons_equal(our, cgal_poly);
        if (match) pass_count++; else fail_count++;
        results.push_back({"Overlapping squares (5,5)-(15,15)", our_empty, cgal_empty, match,
                          polygon_area(our), polygon_area(cgal_poly),
                          (int)our.size(), (int)std::distance(cgal_poly.vertices_begin(), cgal_poly.vertices_end()),
                          ""});
    }

    // 3. Two non-overlapping squares
    {
        total_tests++;
        auto P = make_rectangle(0, 0, 5, 5);
        auto Q = make_rectangle(10, 10, 15, 15);
        auto our = convex_polygon_intersection(P, Q);
        Polygon poly_P(P.begin(), P.end()), poly_Q(Q.begin(), Q.end());
        auto cgal_result = CGAL::intersection(poly_P, poly_Q);

        bool our_empty = our.empty() || our.size() < 3;
        bool cgal_empty = !cgal_result;
        if (match) pass_count++; else fail_count++;
        results.push_back({"Non-overlapping squares", our_empty, cgal_empty,
                          our_empty == cgal_empty, polygon_area(our), 0,
                          (int)our.size(), 0, ""});
    }

    // 4. One inside the other
    {
        total_tests++;
        auto P = make_rectangle(0, 0, 20, 20);
        auto Q = make_rectangle(5, 5, 15, 15);
        auto our = convex_polygon_intersection(P, Q);
        Polygon poly_P(P.begin(), P.end()), poly_Q(Q.begin(), Q.end());
        auto cgal_result = CGAL::intersection(poly_P, poly_Q);

        bool our_empty = our.empty() || our.size() < 3;
        bool cgal_empty = !cgal_result;
        Polygon cgal_poly;
        if (cgal_result) {
            if (auto* pp = std::get_if<Polygon>(&*cgal_result)) cgal_poly = *pp;
            else if (auto* pwh = std::get_if<Polygon_with_holes>(&*cgal_result)) cgal_poly = pwh->outer_boundary();
        }

        bool match = our_empty ? cgal_empty : polygons_equal(our, cgal_poly);
        if (match) pass_count++; else fail_count++;
        results.push_back({"Square inside square", our_empty, cgal_empty, match,
                          polygon_area(our), polygon_area(cgal_poly),
                          (int)our.size(), (int)std::distance(cgal_poly.vertices_begin(), cgal_poly.vertices_end()),
                          ""});
    }

    // 5. Touching at corner
    {
        total_tests++;
        auto P = make_rectangle(0, 0, 10, 10);
        auto Q = make_rectangle(10, 10, 20, 20);
        auto our = convex_polygon_intersection(P, Q);
        Polygon poly_P(P.begin(), P.end()), poly_Q(Q.begin(), Q.end());
        auto cgal_result = CGAL::intersection(poly_P, poly_Q);

        bool our_empty = our.empty() || our.size() < 3;
        bool cgal_empty = !cgal_result;
        if (match) pass_count++; else fail_count++;
        results.push_back({"Touching at corner", our_empty, cgal_empty,
                          our_empty == cgal_empty, polygon_area(our), 0,
                          (int)our.size(), 0, ""});
    }

    // 6. Touching at edge
    {
        total_tests++;
        auto P = make_rectangle(0, 0, 10, 10);
        auto Q = make_rectangle(10, 0, 20, 10);
        auto our = convex_polygon_intersection(P, Q);
        Polygon poly_P(P.begin(), P.end()), poly_Q(Q.begin(), Q.end());
        auto cgal_result = CGAL::intersection(poly_P, poly_Q);

        bool our_empty = our.empty() || our.size() < 3;
        bool cgal_empty = !cgal_result;
        if (match) pass_count++; else fail_count++;
        results.push_back({"Touching at edge", our_empty, cgal_empty,
                          our_empty == cgal_empty, polygon_area(our), 0,
                          (int)our.size(), 0, ""});
    }

    // 7. Triangle-triangle intersection
    {
        total_tests++;
        auto P = make_triangle(0, 0, 10, 0, 5, 10);
        auto Q = make_triangle(3, 3, 13, 3, 8, 13);
        auto our = convex_polygon_intersection(P, Q);
        Polygon poly_P(P.begin(), P.end()), poly_Q(Q.begin(), Q.end());
        auto cgal_result = CGAL::intersection(poly_P, poly_Q);

        bool our_empty = our.empty() || our.size() < 3;
        bool cgal_empty = !cgal_result;
        Polygon cgal_poly;
        if (cgal_result) {
            if (auto* pp = std::get_if<Polygon>(&*cgal_result)) cgal_poly = *pp;
            else if (auto* pwh = std::get_if<Polygon_with_holes>(&*cgal_result)) cgal_poly = pwh->outer_boundary();
        }

        bool match = our_empty ? cgal_empty : polygons_equal(our, cgal_poly);
        if (match) pass_count++; else fail_count++;
        results.push_back({"Triangle-triangle overlap", our_empty, cgal_empty, match,
                          polygon_area(our), polygon_area(cgal_poly),
                          (int)our.size(), (int)std::distance(cgal_poly.vertices_begin(), cgal_poly.vertices_end()),
                          ""});
    }

    // 8. Regular polygons - hexagons
    {
        total_tests++;
        auto P = make_regular_polygon(0, 0, 5, 6);
        auto Q = make_regular_polygon(3, 3, 5, 6);
        auto our = convex_polygon_intersection(P, Q);
        Polygon poly_P(P.begin(), P.end()), poly_Q(Q.begin(), Q.end());
        auto cgal_result = CGAL::intersection(poly_P, poly_Q);

        bool our_empty = our.empty() || our.size() < 3;
        bool cgal_empty = !cgal_result;
        Polygon cgal_poly;
        if (cgal_result) {
            if (auto* pp = std::get_if<Polygon>(&*cgal_result)) cgal_poly = *pp;
            else if (auto* pwh = std::get_if<Polygon_with_holes>(&*cgal_result)) cgal_poly = pwh->outer_boundary();
        }

        bool match = our_empty ? cgal_empty : polygons_equal(our, cgal_poly);
        if (match) pass_count++; else fail_count++;
        results.push_back({"Two overlapping hexagons", our_empty, cgal_empty, match,
                          polygon_area(our), polygon_area(cgal_poly),
                          (int)our.size(), (int)std::distance(cgal_poly.vertices_begin(), cgal_poly.vertices_end()),
                          ""});
    }

    // 9. Diamond inside rectangle
    {
        total_tests++;
        auto P = make_rectangle(-10, -10, 10, 10);
        auto Q = make_regular_polygon(0, 0, 5, 4);  // Diamond
        auto our = convex_polygon_intersection(P, Q);
        Polygon poly_P(P.begin(), P.end()), poly_Q(Q.begin(), Q.end());
        auto cgal_result = CGAL::intersection(poly_P, poly_Q);

        bool our_empty = our.empty() || our.size() < 3;
        bool cgal_empty = !cgal_result;
        Polygon cgal_poly;
        if (cgal_result) {
            if (auto* pp = std::get_if<Polygon>(&*cgal_result)) cgal_poly = *pp;
            else if (auto* pwh = std::get_if<Polygon_with_holes>(&*cgal_result)) cgal_poly = pwh->outer_boundary();
        }

        bool match = our_empty ? cgal_empty : polygons_equal(our, cgal_poly);
        if (match) pass_count++; else fail_count++;
