                  << std::setw(10) << (r.our_empty ? "YES" : "NO")
                  << std::setw(10) << (r.cgal_empty ? "YES" : "NO")
                  << std::setw(8) << (r.match ? "PASS" : "FAIL")
                  << std::setw(15) << r.our_area
                  << std::setw(15) << r.cgal_area << "\n";
    }

    std::cout << std::string(103, '-') << "\n";
    std::cout << "\nTOTAL: " << total_tests << " tests\n";
    std::cout << "PASSED: " << pass_count << "\n";
    std::cout << "FAILED: " << fail_count << "\n";
    std::cout << "SUCCESS RATE: " << std::fixed << std::setprecision(1)
              << (100.0 * pass_count / total_tests) << "%\n";

    if (fail_count > 0) {
        std::cout << "\n!!! FAILURES DETECTED !!!\n";
        std::cout << "Failed tests:\n";
        for (const auto& r : results) {
            if (!r.match) {
                std::cout << "  - " << r.name << "\n";
                std::cout << "    Our result: " << (r.our_empty ? "EMPTY" : std::to_string(r.our_vertices) + " vertices")
                          << ", area=" << r.our_area << "\n";
                std::cout << "    CGAL result: " << (r.cgal_empty ? "EMPTY" : std::to_string(r.cgal_vertices) + " vertices")
                          << ", area=" << r.cgal_area << "\n";
            }
        }
    }

    return fail_count > 0 ? 1 : 0;
