// Helper: get intersection result as a vector of points
bool cgal_polygon_intersection(const Polygon& P, const Polygon& Q,
                                std::vector<Point>& result) {
    result.clear();

    // Ensure polygons are counterclockwise for CGAL operations
    Polygon P_ccw = P;
    Polygon Q_ccw = Q;
    if (!P_ccw.is_counterclockwise_oriented()) {
        P_ccw.reverse_orientation();
    }
    if (!Q_ccw.is_counterclockwise_oriented()) {
        Q_ccw.reverse_orientation();
    }

    if (!CGAL::do_intersect(P_ccw, Q_ccw)) {
        return false;
    }

    using IT = std::variant<Polygon, Polygon_with_holes>;
    std::list<IT> isects;
    CGAL::intersection(P_ccw, Q_ccw, std::back_inserter(isects));

    if (isects.empty()) {
        return false;
    }

    for (const auto& isect : isects) {
        Polygon p;
        if (std::holds_alternative<Polygon>(isect)) {
            p = std::get<Polygon>(isect);
        } else {
            p = std::get<Polygon_with_holes>(isect).outer_boundary();
        }

        for (auto it = p.vertices_begin(); it != p.vertices_end(); ++it) {
            result.push_back(*it);
        }
    }

    return true;
}

