// Helper macro to run a test case
// For convex polygon intersection, we compare:
// 1. Whether there's a non-degenerate (area > 0) polygon intersection
// 2. If both have non-degenerate intersections, whether they match
#define RUN_TEST(name, P, Q) do { \
    total_tests++; \
    auto our = convex_polygon_intersection(P, Q); \
    Polygon poly_P(P.begin(), P.end()), poly_Q(Q.begin(), Q.end()); \
    std::vector<Point> cgal_vec; \
    bool cgal_has_poly = cgal_polygon_intersection(poly_P, poly_Q, cgal_vec); \
    bool our_has_poly = !our.empty() && our.size() >= 3 && polygon_area(our) > 1e-12; \
    bool cgal_has_any = cgal_has_any_intersection(poly_P, poly_Q); \
    bool match; \
    double cgal_a = polygon_area(cgal_vec); \
    int cgal_v = (int)cgal_vec.size(); \
    \
    if (!our_has_poly && !cgal_has_poly) { \
        // Both have no non-degenerate polygon intersection - PASS \
        // (degenerate intersections like points/lines are ignored) \
        match = true; \
    } else if (our_has_poly && cgal_has_poly) { \
